package com.nivor.journal;
import com.nivor.journal.dto.*;import jakarta.validation.Valid;import java.time.LocalDate;import java.util.List;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/journal")public class JournalController{
private final JournalService service;public JournalController(JournalService s){service=s;}@GetMapping public List<JournalResponse> list(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate date,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.list(u.getUsername(),date,from,to).stream().map(JournalResponse::from).toList();}@GetMapping("/{id}")public JournalResponse get(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return JournalResponse.from(service.get(u.getUsername(),id));}@PostMapping public ResponseEntity<JournalResponse> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody JournalRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(JournalResponse.from(service.create(u.getUsername(),r)));}@PutMapping("/{id}")public JournalResponse update(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody JournalRequest r){return JournalResponse.from(service.update(u.getUsername(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}
}
